  function parseDriveFolderId(url){const s=(url||'').trim();const m=s.match(/\/folders\/([a-zA-Z0-9_-]+)/)||s.match(/[?&]id=([a-zA-Z0-9_-]+)/);return m?m[1]:''}
  function moveArrayItem(arr,from,to){const out=[...arr];const [item]=out.splice(from,1);out.splice(to,0,item);return out}
  function listingAllPhotos(listing,vehicle){return [...(vehicle?.photos||[]),...(listing?.listingAssets||[])]}
  function normalizePhotoOrder(listing,vehicle){const all=listingAllPhotos(listing,vehicle),ids=all.map(p=>p.id),raw=Array.isArray(listing?.photoOrder)?listing.photoOrder:[];const cap=arr=>arr.filter((id,i,a)=>id&&a.indexOf(id)===i).slice(0,LISTING_PHOTO_LIMIT);const normalized=cap(raw.map(x=>typeof x==='number'?(vehicle?.photos||[])[x]?.id:x).filter(x=>ids.includes(x)));if(listing?.photoOrderCustomized===true)return normalized;if(normalized.length)return normalized;return cap([...(vehicle?.photos||[]).map(p=>p.id),...(listing?.listingAssets||[]).map(p=>p.id)])}
  function listingPhotoAssetKey(item,vehicleId='manual'){const base=[vehicleId||'manual',String(item?.name||'').toLowerCase(),item?.size||item?.blob?.size||0,item?.lastModified||0,item?.type||item?.blob?.type||''].join('|');let h=2166136261;for(let i=0;i<base.length;i++){h^=base.charCodeAt(i);h=Math.imul(h,16777619)}return `LPA-${(h>>>0).toString(36)}`}

  function accentTextColor(hex){let h=String(hex||'#2563eb').replace('#','').trim();if(h.length===3)h=h.split('').map(x=>x+x).join('');if(!/^[0-9a-fA-F]{6}$/.test(h))return '#fff';const rgb=[0,2,4].map(i=>parseInt(h.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4));const lum=.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2];return lum>=.38?'#111827':'#fff'}
  async function applyPersonalAppearance(){const choice=await setting('personalTheme','system'),accent=await setting('personalAccent','#2563eb')||'#2563eb',accentInk=accentTextColor(accent);document.documentElement.style.setProperty('--accent',accent);document.documentElement.style.setProperty('--accent-ink',accentInk);const dark=choice==='dark'||(choice==='system'&&window.matchMedia?.('(prefers-color-scheme: dark)').matches);document.body.dataset.theme=dark?'dark':'light';document.body.dataset.accentLight=accentInk==='#111827'?'true':'false';const meta=document.querySelector('meta[name=theme-color]');if(meta)meta.setAttribute('content',dark?'#000000':'#f3f4f6');}
  function profileInitials(name){const parts=String(name||'User').trim().split(/\s+/).filter(Boolean);return (parts.slice(0,2).map(x=>x[0]||'').join('')||'U').toUpperCase()}
  async function updateProfileNavIcon(){const el=$('#profile-nav-icon');if(!el)return;const photo=await setting('personalProfilePhoto','');if(photo){el.innerHTML=`<img src="${esc(photo)}" alt="">`;el.classList.add('has-photo')}else{el.textContent='👤';el.classList.remove('has-photo')}}
  async function makeProfilePhotoDataUrl(file){if(!file||!String(file.type||'').startsWith('image/'))throw new Error('Please choose an image file.');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('LotKeys could not read that image. Try a JPG, PNG or WebP file.'));im.src=url});const w=img.naturalWidth||img.width,h=img.naturalHeight||img.height;if(!w||!h)throw new Error('That image has no readable dimensions.');const side=Math.min(w,h),sx=(w-side)/2,sy=(h-side)/2,size=360,canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d');ctx.drawImage(img,sx,sy,side,side,0,0,size,size);return canvas.toDataURL('image/jpeg',.86)}finally{URL.revokeObjectURL(url)}}
  const storeProfileThumbCache=new Map();
  async function blobToDataUrl(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=()=>reject(r.error||new Error('Could not read image'));r.readAsDataURL(blob)})}
  async function storeUserThumbDataUrl(fileId,version=''){if(!fileId)return'';const key=`${fileId}|${version||''}`;if(storeProfileThumbCache.has(key))return storeProfileThumbCache.get(key);try{const blob=await DriveSync.fetchFileBlob(fileId),data=await blobToDataUrl(blob);storeProfileThumbCache.set(key,data);return data}catch{return''}}
