  async function markPersonalProfileChanged(){await setSetting('personalProfileUpdatedAt',Date.now());const folderId=await setting('personalProfileDriveFolderId','');let accountSaved=false;if(!folderId){await setSetting('personalProfileLastSyncError','Choose a LotKeys Account Storage folder to back up personal settings.')}else{try{accountSaved=!!(await DriveSync.syncPersonalProfile());if(accountSaved)await setSetting('personalProfileLastSyncError','')}catch(err){console.warn('Personal Account Drive sync deferred',err);await setSetting('personalProfileLastSyncError',err?.message||String(err))}}try{if(DriveSync.connected()&&await DriveSync.ready()){await DriveSync.syncStoreProfileThumbnail();await setSetting('storeProfileThumbnailLastSyncError','');storeProfileThumbCache.clear();await hydrateStoreProfileThumbs(document)}}catch(err){console.warn('Store public profile sync deferred',err);await setSetting('storeProfileThumbnailLastSyncError',err?.message||String(err))}return accountSaved}

  async function descriptionTemplateOptions(selected=''){const rows=await DescriptionTemplates.all();return rows.map(t=>`<option value="${esc(t.id)}" ${t.id===selected?'selected':''}>${esc(t.name)}</option>`).join('')}
  function bindDescriptionBlockReorder(container,onMove){if(!container)return;let from=null,active=null,pointerId=null,target=null;const blocks=()=>[...container.querySelectorAll('.description-block')];const at=(x,y)=>{const exact=document.elementFromPoint(x,y)?.closest?.('.description-block');if(exact&&container.contains(exact)&&exact!==active)return exact;let best=null,dist=Infinity;for(const b of blocks()){if(b===active)continue;const r=b.getBoundingClientRect(),d=(y-(r.top+r.height/2))**2+(x-(r.left+r.width/2))**2;if(d<dist){dist=d;best=b}}return best};const clear=()=>container.querySelectorAll('.dragging,.drop-target').forEach(x=>x.classList.remove('dragging','drop-target'));const move=e=>{if(from===null||e.pointerId!==pointerId)return;e.preventDefault();container.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));target=at(e.clientX,e.clientY);target?.classList.add('drop-target')};const cleanup=()=>{document.removeEventListener('pointermove',move,true);document.removeEventListener('pointerup',up,true);document.removeEventListener('pointercancel',cancel,true)};const up=e=>{if(from===null||e.pointerId!==pointerId)return;e.preventDefault();const hit=at(e.clientX,e.clientY)||target,to=hit?+hit.dataset.pos:from,old=from;clear();cleanup();from=null;active=null;pointerId=null;target=null;if(Number.isFinite(to)&&to!==old)onMove(old,to)};const cancel=e=>{if(from===null)return;clear();cleanup();from=null;active=null;pointerId=null;target=null};container.querySelectorAll('.description-drag').forEach(h=>h.onpointerdown=e=>{const block=h.closest('.description-block');from=+block.dataset.pos;active=block;pointerId=e.pointerId;block.classList.add('dragging');h.setPointerCapture?.(pointerId);document.addEventListener('pointermove',move,true);document.addEventListener('pointerup',up,true);document.addEventListener('pointercancel',cancel,true);e.preventDefault()})}
  function descriptionBlockSettingsHtml(block){const type=block.type,c=block.config||{};if(type==='headline')return `<div class="field"><label>Layout</label><input data-config="pattern" value="${esc(c.pattern||'{{YEAR}} {{MAKE}} {{MODEL}} | {{ODOMETER}}')}"><div class="help">Available: {{YEAR}}, {{MAKE}}, {{MODEL}}, {{ENGINE}}, {{HP}}, {{ENGINE_HP}}, {{ODOMETER}}, {{CLASS}}, {{DRIVETRAIN}}, {{PRICE}}</div></div>`;if(type==='details'){const fields=c.fields||['year','makeModel','drivetrain','odometer','vin','stock'],labels=[['year','Year'],['makeModel','Make / Model'],['drivetrain','Drivetrain'],['odometer','Odometer'],['vin','VIN'],['stock','STK']];return `<div class="description-feature-grid">${labels.map(([k,l])=>`<label class="description-feature-choice"><input type="checkbox" data-detail-field="${k}" ${fields.includes(k)?'checked':''}> ${l}</label>`).join('')}</div>`}if(type==='overview')return `<div class="form-grid"><div class="field"><label>Approx. sentences</label><input type="number" min="1" max="6" data-config="sentences" value="${esc(c.sentences||3)}"></div></div><div class="field"><label>Writing guidance</label><textarea data-config="guidance">${esc(c.guidance||'Keep it factual and focus on the strongest buyer benefits.')}</textarea><div class="help">Saved with the template now; this becomes useful when we plug in the AI-assisted wording layer.</div></div>`;if(type==='features')return `<div class="field"><label>Maximum feature bullets</label><input type="number" min="3" max="40" data-config="limit" value="${esc(c.limit||20)}"></div>`;if(type==='topFeatures')return `<div class="field"><label>How many standout items?</label><input type="number" min="3" max="8" data-config="count" value="${esc(c.count||5)}"></div>`;if(type==='price')return `<div class="field"><label>Price wording</label><textarea data-config="text">${esc(c.text||'{{PRICE}} + GST')}</textarea><div class="help">Use {{PRICE}} where the Vehicle Profile price belongs.</div></div>`;if(type==='financing'||type==='signature'||type==='custom')return `<div class="field"><label>${type==='signature'?'Signature text':type==='financing'?'Financing wording':'Custom text'}</label><textarea data-config="text">${esc(c.text||'')}</textarea><div class="help">{{USER_NAME}}, {{PRICE}}, {{YEAR}}, {{MAKE}}, {{MODEL}} and other template variables are supported.</div></div>`;return''}
  async function showDescriptionTemplateEditor(source=null){let t=source?(source.builtIn?DescriptionTemplates.cloneForUser(source):structuredClone(source)):{id:uid('TPL'),name:'My Marketplace Template',builtIn:false,description:'My custom description recipe.',blocks:[DescriptionTemplates.defaultBlock('headline',{useEmojis:false,config:{pattern:'{{YEAR}} {{MAKE}} {{MODEL}} | {{ODOMETER}} | {{CLASS}}'}}),DescriptionTemplates.defaultBlock('overview'),DescriptionTemplates.defaultBlock('features',{config:{limit:15}}),DescriptionTemplates.defaultBlock('price',{config:{text:'{{PRICE}} + GST'}}),DescriptionTemplates.defaultBlock('signature',{useEmojis:false,config:{text:'Message {{USER_NAME}} to set up a viewing or to book.'}})]};
    const renderBlocks=()=>{const box=$('#description-block-list');if(!box)return;box.innerHTML=t.blocks.map((b,i)=>`<div class="description-block" data-pos="${i}"><div class="description-block-head"><button type="button" class="description-drag" aria-label="Move section">≡</button><div class="description-block-title"><strong>${esc(b.title||DescriptionTemplates.BLOCK_LABELS[b.type]||b.type)}</strong><small>${esc(DescriptionTemplates.BLOCK_LABELS[b.type]||b.type)}</small></div><div class="description-block-toggles"><label><input type="checkbox" data-enabled ${b.enabled!==false?'checked':''}> Use</label><label><input type="checkbox" data-emojis ${b.useEmojis!==false?'checked':''}> Emoji</label></div></div><details><summary>Customize section</summary><div class="description-block-settings"><div class="field"><label>Section name</label><input data-block-title value="${esc(b.title||DescriptionTemplates.BLOCK_LABELS[b.type]||'Section')}"></div>${descriptionBlockSettingsHtml(b)}<button type="button" class="btn danger description-block-delete">Remove Section</button></div></details></div>`).join('');box.querySelectorAll('.description-block').forEach((el,i)=>{const b=t.blocks[i];el.querySelector('[data-enabled]').onchange=e=>b.enabled=e.target.checked;el.querySelector('[data-emojis]').onchange=e=>b.useEmojis=e.target.checked;el.querySelector('[data-block-title]').oninput=e=>b.title=e.target.value;el.querySelectorAll('[data-config]').forEach(inp=>inp.oninput=e=>{let v=e.target.value;if(e.target.type==='number')v=+v;b.config=b.config||{};b.config[e.target.dataset.config]=v});el.querySelectorAll('[data-detail-field]').forEach(inp=>inp.onchange=()=>{b.config=b.config||{};b.config.fields=[...el.querySelectorAll('[data-detail-field]:checked')].map(x=>x.dataset.detailField)});el.querySelector('.description-block-delete').onclick=()=>{t.blocks.splice(i,1);renderBlocks()}});bindDescriptionBlockReorder(box,(from,to)=>{t.blocks=moveArrayItem(t.blocks,from,to);renderBlocks()})};
    modalBody.innerHTML=`<div class="modal-head"><div><div class="eyebrow">DESCRIPTION TEMPLATE TOOL</div><h2>${source?'Customize Template':'Create Template'}</h2></div><button class="close">×</button></div><form id="description-template-form"><div class="field"><label>Template Name</label><input id="description-template-name" required value="${esc(t.name)}"></div><div class="help">Drag the ≡ handle to stack the sections in the order you want. Turn sections or emojis on/off without writing a prompt.</div><div class="template-add-row"><select id="description-add-type">${Object.entries(DescriptionTemplates.BLOCK_LABELS).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select><button type="button" class="btn" id="description-add-block">＋ Add Block</button></div><div id="description-block-list" class="description-block-list"></div><div class="actions"><button class="btn primary" type="submit">Save Description Template</button></div></form>`;modalBody.querySelector('.close').onclick=()=>modal.close();
renderBlocks();$('#description-add-block').onclick=()=>{const type=$('#description-add-type').value,block=DescriptionTemplates.defaultBlock(type);if(type==='price')block.config.text='{{PRICE}} + GST';if(type==='financing')block.config.text='Flexible financing options\nOAC (On Approved Credit)\nExtended warranty options available';if(type==='signature')block.config.text='Message {{USER_NAME}} to set up a viewing or to book.';t.blocks.push(block);renderBlocks()};$('#description-template-form').onsubmit=async e=>{e.preventDefault();t.name=$('#description-template-name').value.trim()||'My Marketplace Template';await DescriptionTemplates.save(t);await setSetting('lastDescriptionTemplateId',t.id);await markPersonalProfileChanged();modal.close();toast('Description template saved ✓');if(route==='profile')render()};if(!modal.open)modal.showModal()}


  function paintProtocolState(st){const n=$('#local-test-note');if(!n||!st)return;const cls=st.level==='good'?'protocol-good':st.level==='bad'?'protocol-bad protocol-attention':'protocol-attention',label=st.level==='good'?'Authorized':st.level==='warn'?'Attention':'Action needed';n.className=`protocol-warning ${cls}`;n.innerHTML=`<strong>LotKeys Drive Test · V0.9.4.6</strong> — ${label}<button class="protocol-info-btn" id="version-info-btn" type="button" aria-label="What is new in this LotKeys version">ℹ️</button>`;$('#version-info-btn')?.addEventListener('click',showVersionInfo)}
  async function updateProtocolNote(){paintProtocolState(await getReadinessState())}
  async function showVersionInfo(){const signed=!!(await setting('currentAccountEmail','')),st=await getReadinessState();modalBody.innerHTML=`<div class="modal-head"><div><div class="eyebrow">LOTKEYS V0.9.4.6</div><h2>What’s new</h2></div><button class="close">×</button></div><div class="card" style="box-shadow:none"><div class="readiness-hero ${st.level}" style="margin-bottom:10px"><span class="readiness-big-dot ${st.level}"></span><div><strong>${esc(st.title)}</strong><div class="small" style="margin-top:4px">${esc(st.summary)}</div></div></div>${st.issues?.length?`<ul class="points-info-list">${st.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<ul class="points-info-list"><li><strong>Facebook Assistant Beta:</strong> desktop Chrome can now use the companion LotKeys side-panel extension to transfer saved Listing fields and ordered photos into Facebook Marketplace.</li><li><strong>Marketplace Listing photos are now capped at 20.</strong> Vehicle Profile photos and salesperson-added photos share the same 20-photo limit, with a selector for choosing which Profile photos are included.</li><li>Vehicle Profiles now include Body Style, Exterior Color, Interior Color, Vehicle Condition and Fuel Type for Facebook form assistance. Blank values stay manual.</li><li><strong>Rebuilt from the stable v0.9.3.3 baseline</strong> so the working navigation, readiness, Store connection, Listings, Inventory and media upload code stays intact.</li><li>Top Contributors supports personal accent rings, smoother gradient gold/silver/bronze monthly rings, Last Month history and the Admin month-end wrap-up flow.</li><li><strong>Month-End Reveal test mode:</strong> Admin Level 2 now has a Test Month-End Wrap-Up button that creates nine simulated competitors plus the current user, guarantees the current user finishes #1, runs the real configured timing/audio/reveal pipeline, and saves no Store standings or history.</li><li><strong>Monthly Reveal controls:</strong> Admin Level 2 can set Build up time from 1–60 seconds and optionally choose when the Final Push begins. Leaving Final Push blank runs the contribution buildup for the full time and jumps directly to the podium.</li><li><strong>Custom reveal audio:</strong> Admin Level 2 can upload a Build up Soundtrack and a Reveal sound from Advanced Google / Store controls. LotKeys preloads reveal media before a race-style 3 · 2 · 1 · GO countdown.</li><li><strong>Personal Celebration Sounds:</strong> every user can keep a personal library of under-10-second clips in their LotKeys Account, select one current clip, and sync only that selected clip into their Store user profile. The winner clip plays after the podium Reveal sound.</li><li>Monthly replays use the winner’s currently selected Celebration Sound from their Store profile; no historical winner-audio copies are created. Store-level Build up and Reveal audio now overwrite their existing canonical files instead of accumulating replacements. The louder party-popper with landing ticks remains the built-in Reveal sound fallback.</li><li>Public profile winner rings are now locked concentrically to the avatar instead of inheriting inline-span positioning.</li><li>Healthy Store synchronization now updates the header and version card together — green <strong>Authorized</strong> appears automatically after connection restores.</li><li>The Store action now reads <strong>Connected to Store ✓</strong> when healthy; Reconnect appears only when authorization really needs recovery.</li><li>Video uploads use a faster adaptive resumable transfer path with much larger video chunks, live transfer progress and fewer Google Drive round trips.</li><li>Unchanged photo/document folders are skipped when only a video changed, so video transfer starts sooner.</li><li>LotKeys requests a temporary screen wake lock during an active video transfer when the browser supports it, helping prevent an accidental screen lock from pausing the upload.</li></ul>${signed?'':'<div class="notice warning"><strong>New here?</strong><div class="small muted" style="margin-top:5px">Open Account and tap <strong>Click to Sign In</strong>, then use the Store Code your management team gives you.</div></div>'}</div>`;modalBody.querySelector('.close').onclick=()=>modal.close();if(!modal.open)modal.showModal()}

  function readLiveProgressRows(){try{return JSON.parse(localStorage.getItem(LIVE_MEDIA_PROGRESS_STORAGE)||'{}')||{}}catch{return {}}}
  function writeLiveProgressRows(rows){try{localStorage.setItem(LIVE_MEDIA_PROGRESS_STORAGE,JSON.stringify(rows||{}))}catch{}}
  function restoreLiveMediaProgress(){const rows=readLiveProgressRows(),now=Date.now();for(const [id,row] of Object.entries(rows)){if(!row||now-(Number(row.updatedAt)||0)>7*86400000)continue;liveMediaProgress.set(id,{...row,status:row.status==='uploading'?'paused':row.status})}}
  function persistLiveMediaProgress(id,state,force=false){if(!id||!state)return;const now=Date.now(),last=liveProgressPersistAt.get(id)||0;if(!force&&state.status==='uploading'&&now-last<1200)return;liveProgressPersistAt.set(id,now);const rows=readLiveProgressRows();rows[id]={folder:state.folder||'Media',kind:state.kind||'',status:state.status||'uploading',percent:Math.max(0,Math.min(100,Number(state.percent)||0)),loadedBytes:Number(state.loadedBytes)||0,totalBytes:Number(state.totalBytes)||0,fileName:state.fileName||'',fileIndex:Number(state.fileIndex)||0,fileCount:Number(state.fileCount)||0,updatedAt:state.updatedAt||now};writeLiveProgressRows(rows)}
  function clearLiveMediaProgress(id){liveMediaProgress.delete(id);liveProgressPersistAt.delete(id);const rows=readLiveProgressRows();if(rows[id]){delete rows[id];writeLiveProgressRows(rows)}}
  function mediaStateForVehicle(v){return liveMediaProgress.get(String(v?.id||''))||v?.mediaUpload||null}
  function activeLiveMediaProgress(){let best=null;for(const [vehicleId,state] of liveMediaProgress){if(state?.status!=='uploading')continue;if(!best||Number(state.updatedAt||0)>Number(best.state.updatedAt||0))best={vehicleId,state}}return best}
  function paintLiveUploadHeader(){const active=activeLiveMediaProgress(),label=$('#sync-status-text'),dot=$('#sync-readiness');if(!active||!label)return false;const pct=Math.max(0,Math.min(100,Number(active.state.percent)||0));label.textContent=`${active.state.folder||'Media'} ${pct}%`;label.className='sync-status-text good';label.title='Media upload in progress';if(dot){dot.className='readiness-btn good';dot.title='LotKeys is ready · media upload in progress';dot.setAttribute('aria-label','LotKeys is ready · media upload in progress')}return true}
  function mediaProgressText(media){if(!media)return'';const pct=Math.max(0,Math.min(100,Number(media.percent)||0)),folder=media.folder||'Media';if(media.status==='paused')return `${folder} · paused at ${pct}%`;if(media.status==='error')return `${folder} · upload needs attention`;if(media.status==='complete')return `${folder} · 100%`;return `${folder} · Uploading ${pct}%`}
  function updateVehicleUploadDom(v){const card=document.querySelector(`.open-vehicle[data-id="${CSS.escape(String(v.id))}"]`);if(!card)return;const media=mediaStateForVehicle(v),el=card.querySelector('[data-upload-status]');if(el){el.textContent=mediaProgressText(media);el.className=`vehicle-upload-status ${media?.status==='paused'?'paused':media?.status==='error'?'error':''}`;}const meta=card.querySelector('.meta');if(meta&&media?.status==='uploading')meta.textContent=`STK# ${v.stock||'—'} • ${fmtOdo(v.odometer)} ${v.odometerUnit||'KM'} • Syncing media…`;}
  function setVehicleMediaProgress(v,progress){const state={...progress,updatedAt:Date.now()};v.mediaUpload=state;liveMediaProgress.set(String(v.id),state);persistLiveMediaProgress(String(v.id),state,progress.status!=='uploading'||Number(progress.percent)>=100);updateVehicleUploadDom(v);paintLiveUploadHeader()}
  async function syncVehicleNow(v,{quiet=false,force=false}={}){
    if(!DriveSync.connected()||!(await DriveSync.ready())){v.syncStatus='local';await DB.put('vehicles',v);await updateReadinessIndicator({force:true});if(!quiet)toast('Saved locally — connect Drive to sync');if(!modal.open&&(route==='home'||route==='vehicles'))render();return v;}
    // Keep the already-persisted pending Vehicle Profile as the durable state. Avoid
    // another giant IndexedDB write just to change pending -> syncing before media starts.
    v.syncStatus='syncing';v.syncError='';if(!quiet)toast('Vehicle saved · media will continue in the background');
    try{
      const out=await DriveSync.syncVehicle(v,{force,onProgress:p=>setVehicleMediaProgress(v,p)});clearLiveMediaProgress(String(v.id));await updateReadinessIndicator({force:true});if(!quiet)toast('Vehicle synced to Drive ✓');if(!modal.open&&(route==='home'||route==='vehicles'))render();return out;
    }catch(err){
      const transientMedia=err?.code==='MEDIA_UPLOAD_INTERRUPTED'||(err?.stage==='media'&&([408,429,500,502,503,504].includes(Number(err?.status))||err?.name==='TypeError'));
      if(transientMedia){
        const current=mediaStateForVehicle(v)||{},folder=err.mediaFolder||current.folder||'Media';v.syncStatus='pending';v.syncError='';v.mediaUpload={...current,folder,status:'paused',percent:Number(current.percent)||0,message:err.message||'Upload paused',updatedAt:Date.now()};liveMediaProgress.set(String(v.id),v.mediaUpload);persistLiveMediaProgress(String(v.id),v.mediaUpload,true);await DB.put('vehicles',v);await updateReadinessIndicator({force:true});if(!modal.open&&(route==='home'||route==='vehicles'))render();if(!quiet)toast(`${folder} upload paused · LotKeys saved the checkpoint`);if(document.visibilityState!=='hidden'&&navigator.onLine!==false)setTimeout(()=>queueVehicleSync(v),3000);return v;
      }
      const current=mediaStateForVehicle(v);v.syncStatus='error';v.syncError=err.message||String(err);if(current){v.mediaUpload={...current,status:'error',updatedAt:Date.now()};liveMediaProgress.set(String(v.id),v.mediaUpload);persistLiveMediaProgress(String(v.id),v.mediaUpload,true)}await DB.put('vehicles',v);await updateReadinessIndicator({force:true});if(!modal.open&&(route==='home'||route==='vehicles'))render();if(!quiet)toast('Saved locally — Drive sync needs attention');return v;
    }
  }
  function queueVehicleSync(v,{force=false}={}){
    if(!v?.id)return Promise.resolve(v);
    const running=vehicleSyncJobs.get(v.id);if(running)return running;
    v.syncStatus='pending';
    const job=Promise.resolve().then(()=>syncVehicleNow(v,{quiet:true,force})).catch(err=>{console.warn(err);return v}).finally(()=>vehicleSyncJobs.delete(v.id));
    vehicleSyncJobs.set(v.id,job);return job;
  }
  async function resumePendingVehicleSyncs(){if(!DriveSync.connected()||!(await DriveSync.ready()))return;const pending=(await DB.all('vehicles')).filter(v=>['pending','syncing'].includes(v.syncStatus)||v.mediaUpload?.status==='paused');for(const v of pending)queueVehicleSync(v)}
  async function refreshInventory({quiet=true,forceFull=false}={}){if(inventoryRefreshBusy||modal.open||!DriveSync.connected()||!(await DriveSync.ready()))return;inventoryRefreshBusy=true;await updateReadinessIndicator();if(!modal.open&&(route==='home'||route==='vehicles'))await render();try{const n=forceFull?await DriveSync.refreshInventoryFromDrive({quiet,forceFull:true}):await DriveSync.quickRefreshInventoryFromDrive({quiet});if(!quiet)toast(`Inventory refreshed · ${n} vehicles`);}catch(err){if(!quiet)alert('Could not refresh Store inventory:\n\n'+err.message);else console.warn('Inventory refresh failed',err);}finally{inventoryRefreshBusy=false;await updateReadinessIndicator();if(!modal.open&&(route==='home'||route==='vehicles'))await render()}}
