  async function syncListingNow(l,{quiet=false}={}){if(!DriveSync.connected()||!(await DriveSync.ready())){l.syncStatus='local';await DB.put('listings',l);await updateReadinessIndicator();if(!quiet)toast('Listing saved locally — connect Drive to sync');if(!modal.open&&(route==='home'||route==='listings'))render();return l;}l.syncStatus='syncing';await DB.put('listings',l);await updateReadinessIndicator();if(!modal.open&&(route==='home'||route==='listings'))render();try{const out=await DriveSync.syncListing(l);await updateReadinessIndicator();if(!quiet)toast('Listing synced to your Drive folder ✓');if(!modal.open&&(route==='home'||route==='listings'))render();return out}catch(err){l.syncStatus='error';l.syncError=err.message||String(err);await DB.put('listings',l);await updateReadinessIndicator();if(!modal.open&&(route==='home'||route==='listings'))render();if(!quiet)alert('Listing saved locally, but Drive sync failed:\n\n'+l.syncError);return l}}
  async function copyText(text,label='Copied'){if(!text)return;try{await navigator.clipboard.writeText(text);toast(label)}catch{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast(label)}}
  function bindPhotoReorder(container,onMove){
    if(!container)return;
    let from=null,activeTile=null,pointerId=null,lastTarget=null;
    const tiles=()=>[...container.querySelectorAll('.photo-tile')];
    const clearTargets=()=>container.querySelectorAll('.drop-target,.dragging').forEach(x=>x.classList.remove('drop-target','dragging'));
    const targetAt=(x,y)=>{
      const exact=document.elementFromPoint(x,y)?.closest?.('.photo-tile');
      if(exact&&container.contains(exact)&&exact!==activeTile)return exact;
      // On touch screens the finger can sit in the grid gap. Choose the closest tile center
      // so dropping between photos still feels natural.
      let best=null,bestDist=Infinity;
      for(const tile of tiles()){
        if(tile===activeTile)continue;
        const r=tile.getBoundingClientRect();
        const dx=x-(r.left+r.width/2),dy=y-(r.top+r.height/2),d=dx*dx+dy*dy;
        if(d<bestDist){bestDist=d;best=tile;}
      }
      return best;
    };
    const move=e=>{
      if(from===null||e.pointerId!==pointerId)return;
      e.preventDefault();
      container.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));
      lastTarget=targetAt(e.clientX,e.clientY);
      if(lastTarget)lastTarget.classList.add('drop-target');
    };
    const cleanup=()=>{
      document.removeEventListener('pointermove',move,true);
      document.removeEventListener('pointerup',finish,true);
      document.removeEventListener('pointercancel',cancel,true);
      document.body.style.removeProperty('user-select');
      document.body.style.removeProperty('-webkit-user-select');
    };
    const finish=e=>{
      if(from===null||e.pointerId!==pointerId)return;
      e.preventDefault();
      const under=targetAt(e.clientX,e.clientY)||lastTarget;
      const to=under?+under.dataset.pos:from;
      const old=from;
      clearTargets();cleanup();
      from=null;activeTile=null;pointerId=null;lastTarget=null;
      if(Number.isFinite(to)&&to!==old)onMove(old,to);
    };
    const cancel=e=>{
      if(from===null||(e.pointerId!=null&&e.pointerId!==pointerId))return;
      clearTargets();cleanup();
      from=null;activeTile=null;pointerId=null;lastTarget=null;
    };
    container.querySelectorAll('.drag-handle').forEach(handle=>{
      handle.onpointerdown=e=>{
        if(from!==null)return;
        const tile=handle.closest('.photo-tile');
        if(!tile)return;
        from=+tile.dataset.pos;activeTile=tile;pointerId=e.pointerId;lastTarget=null;
        tile.classList.add('dragging');
        document.body.style.userSelect='none';document.body.style.webkitUserSelect='none';
        handle.setPointerCapture?.(e.pointerId);
        document.addEventListener('pointermove',move,{capture:true,passive:false});
        document.addEventListener('pointerup',finish,{capture:true,passive:false});
        document.addEventListener('pointercancel',cancel,{capture:true,passive:false});
        e.preventDefault();e.stopPropagation();
      };
    });
  }


  function syncCardClass(syncStatus,businessStatus=''){
    if(syncStatus==='error')return 'sync-error';
    if(!DriveSync.connected()||['local','pending','syncing'].includes(syncStatus)||String(businessStatus||'').toLowerCase()==='pending')return 'sync-pending';
    return '';
  }
  async function getReadinessState(){
    const ds=await DriveSync.getStatus(),ready=await DriveSync.ready(),userName=await setting('userName','');
    const issues=[];
    if(!ds.isHttps)issues.push('LotKeys must be opened from the hosted HTTPS address for Google Drive.');
    if(!ds.configured)issues.push('Google OAuth is not configured.');
    if(driveConnectInProgress && ds.isHttps && ds.configured){return {level:'warn',title:'Connecting to Store',summary:'Authorization is complete or in progress while LotKeys confirms your Store connection.',issues:['Keep LotKeys open for a moment. If this does not finish, tap Refresh Status or Reconnect to Store.'],pending:0,errors:0};}
    if(!ds.storeFolderId)issues.push('No Store is connected.');
    if(!userName)issues.push('No LotKeys user is registered on this device.');
    if(issues.length)return {level:'bad',title:'Setup needs attention',summary:'LotKeys is not fully ready.',issues,pending:0,errors:0};
    if(!ready||!ds.connected)return {level:'warn',title:'Reconnect to Store',summary:'Your Store is saved, but this browser is not currently authorized with Google Drive.',issues:['Tap Reconnect to Store. LotKeys will try the lightest authorization refresh first.'],pending:0,errors:0};
    return {level:'good',title:'Synced and ready',summary:'Your LotKeys account and Store connection are healthy.',issues:[],pending:0,errors:0};
  }
  async function updateReadinessIndicator({force=false}={}){
    const b=$('#sync-readiness'),label=$('#sync-status-text');if(!b)return;
    // While media is actively moving, use the in-memory progress source directly.
    // This avoids reading every Vehicle record (including large video Blobs) just to
    // repaint the tiny header label, which was stalling tab changes in v0.8.9.1/2.
    if(!force&&paintLiveUploadHeader())return;
    const st=await getReadinessState();
    paintProtocolState(st);
    b.className=`readiness-btn ${st.level}`;
    b.setAttribute('aria-label',st.title);
    b.title=st.title;
    if(label){
      let text='Please Sync';
      const activeUpload=activeLiveMediaProgress();
      if(driveConnectInProgress)text='Connecting…';
      else if(activeUpload)text=`${activeUpload.state.folder||'Media'} ${Math.max(0,Math.min(100,Number(activeUpload.state.percent)||0))}%`;
      else if(inventoryRefreshBusy||listingsRefreshBusy)text='Syncing…';
      else if(st.level==='good'){
        const inv=+(await setting('lastInventoryRefreshAt',0))||0,lis=+(await setting('lastListingsRefreshAt',0))||0;
        const last=route==='vehicles'?inv:route==='listings'?lis:(inv&&lis?Math.min(inv,lis):(inv||lis));
        text=last?`Sync ${fmtTime12(last)}`:'Ready';
      }else if(st.level==='bad')text=st.errors?'Sync Error':'Setup Needed';
      else if(st.level==='warn')text='Please Sync';
      label.textContent=text;label.className=`sync-status-text ${st.level}`;label.title=st.title;
    }
  }
  async function showReadinessModal(){
    const st=await getReadinessState();
    modalBody.innerHTML=`<div class="modal-head"><h2>LotKeys readiness</h2><button class="close">×</button></div>
      <div class="readiness-hero ${st.level}"><span class="readiness-big-dot ${st.level}"></span><div><strong>${esc(st.title)}</strong><div class="small" style="margin-top:4px">${esc(st.summary)}</div></div></div>
      ${st.issues.length?`<div class="card" style="box-shadow:none"><strong>What to do</strong><ul style="margin:9px 0 0;padding-left:20px">${st.issues.map(x=>`<li style="margin:6px 0">${esc(x)}</li>`).join('')}</ul></div>`:''}
      <div class="actions"><button class="btn primary" id="readiness-settings">Open Garage</button><button class="btn ghost" id="readiness-refresh">Refresh Status</button></div>`;
    modalBody.querySelector('.close').onclick=()=>modal.close();
    $('#readiness-settings').onclick=()=>{modal.close();go('settings')};
    $('#readiness-refresh').onclick=async()=>{const b=$('#readiness-refresh');b.disabled=true;b.textContent='Checking…';try{const result=await DriveSync.healthCheck();toast(result.message||'Status refreshed')}catch(err){if(err?.code==='STORE_BLOCKED'){await showStoreBlockedMessage('');return}toast(err.message||'Connection needs attention')}finally{await updateReadinessIndicator({force:true});updateProtocolNote();if(b?.isConnected){b.disabled=false;b.textContent='Refresh Status'}showReadinessModal()}};
    if(!modal.open)modal.showModal();
  }
  async function boot(){
    await DB.open();
    await validatePersonalTagline();
    await ensureDefaults();
    if(await setting('priceAlertLogicVersion','')!=='0921'){await clearLegacyWebsiteWarnings();await setSetting('lastPriceCheckAt',0);await setSetting('priceAlertLogicVersion','0921')}
    await applyPersonalAppearance();
    await DriveSync.restoreSessionAuthorization();
    if(DriveSync.connected()){await DriveSync.loadPersonalProfile().catch(err=>console.warn('Personal profile restore deferred',err));await applyPersonalAppearance();}
    await updateProtocolNote();
    $('#quick-add').onclick=async()=>{const canCreate=await currentUserCan('createVehicleProfiles'),canList=await currentUserCan('useListings');if(!canCreate&&!canList){toast('Your account cannot create Vehicles or Listings right now.');return}showCreateChooser()};
    $('#sync-readiness').onclick=()=>showReadinessModal();
    if($('#sync-status-text')){$('#sync-status-text').onclick=()=>showReadinessModal();$('#sync-status-text').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showReadinessModal()}}}
    document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>go(b.dataset.route));
    document.addEventListener('click',e=>{const el=e.target.closest?.('.open-public-profile');if(el?.dataset?.userName&&!el.closest('#modal-body .public-profile-shell')){e.preventDefault();showPublicUserProfile(el.dataset.userName)}});
    if('serviceWorker' in navigator && (location.protocol==='https:' || location.hostname==='localhost')) {
      navigator.serviceWorker.register('./sw.js?v=0946', {updateViaCache:'none'})
        .then(reg=>reg.update().catch(()=>{}))
        .catch(()=>{});
    }
    inventoryRefreshTimer=setInterval(()=>{refreshInventory({quiet:true});refreshListings({quiet:true});},5*60*1000);
    document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){resumePendingVehicleSyncs().catch(console.warn);refreshInventory({quiet:true});refreshListings({quiet:true});}});
    window.addEventListener('focus',()=>{resumePendingVehicleSyncs().catch(console.warn);refreshInventory({quiet:true});refreshListings({quiet:true});});
    if(DriveSync.connected() && await DriveSync.ready()){await DriveSync.loadStoreConfig().catch(err=>console.warn('Store branding restore deferred',err));}
    await render();
    maybeShowMonthlyReveal().catch(console.warn);
    if(DriveSync.connected() && await DriveSync.ready()){
      refreshInventory({quiet:true}).catch(console.warn);
      refreshListings({quiet:true}).catch(console.warn);
      await resumePendingVehicleSyncs();
      DriveSync.syncPersonalProfile({preferRemote:true}).then(()=>DriveSync.syncStoreProfileThumbnail()).catch(console.warn);
    }
  }

  function userKey(u={}){return String(u.googleSub||u.email||u.userName||'').trim().toLowerCase()}
  function defaultUserPermissions(overrides={}){return {createVehicleProfiles:true,markVehicleForDeletion:true,useListings:true,showOnLeaderboard:true,useDescriptionBuilder:true,useChromeExtension:true,...(overrides||{})}}
  function defaultModerationStats(overrides={}){return {submitted:0,approved:0,dismissed:0,falseReports:0,...(overrides||{})}}
  function normalizedAdminLevel(user={}){const raw=user.adminLevel!=null?Number(user.adminLevel):(user.role==='admin'?2:0);return Math.max(0,Math.min(2,Number.isFinite(raw)?raw:0))}
  function normalizeUserAccount(user={}){const permissions=defaultUserPermissions(user.permissions||{}),moderation=defaultModerationStats(user.moderation||{}),contributions=defaultContributionStats(user.contributions||{}),adminLevel=normalizedAdminLevel(user);return {...user,adminLevel,role:adminLevel>0?'admin':'user',status:user.status||'active',permissions,moderation,contributions}}
  function normalizeStoreUsers(users=[]){const seen=new Set(),out=[];for(const raw of Array.isArray(users)?users:[]){const u=normalizeUserAccount(raw||{}),key=userKey(u);if(key&&seen.has(key))continue;if(key)seen.add(key);out.push(u)}return out}
  function findStoreUser(users,userName='',email=''){users=normalizeStoreUsers(users);const lowerName=String(userName||'').trim().toLowerCase(),lowerEmail=String(email||'').trim().toLowerCase();return users.find(u=>(lowerName&&String(u.userName||'').trim().toLowerCase()===lowerName)||(lowerEmail&&String(u.email||'').trim().toLowerCase()===lowerEmail))||null}
  function adminLevelLabel(level=0){level=Number(level)||0;return level>=2?'Admin Level 2':level===1?'Admin Level 1':'User'}
  function taglineValid(v){v=String(v||'');if(!v)return true;if(v.length>20)return false;return /^[A-Za-z0-9 À-ÖØ-öø-ÿ'".,!?&+\-()/:;#]*$/.test(v)}
  function cleanTagline(v){v=String(v||'').trim();return taglineValid(v)?v.slice(0,20):''}
  function userLotLevel(u={}){return Math.max(0,Number(u.lotLevel)||0)}
  function userFavoriteBadge(u={}){return String(u.favoriteBadge||'').trim()}
  function safeAccentColor(v='#2563eb'){v=String(v||'').trim();return /^#[0-9a-f]{6}$/i.test(v)?v:'#2563eb'}
  function placementClass(u={}){const p=Number(u.monthlyPlacement||0);return p===1?'gold':p===2?'silver':p===3?'bronze':''}
  function awardAvatarHtml(u={},cls='store-user-avatar',wrapClass=''){const initials=profileInitials(u.profileDisplayName||u.userName||'User'),fileId=u.profilePhotoFileId||'',ver=u.profileUpdatedAt||'',pc=placementClass(u),extra=String(wrapClass||'').trim(),accent=safeAccentColor(u.profileAccent||'#2563eb'),crown=Number(u.monthlyPlacement||0)===1?'<span class="avatar-crown" aria-label="Top Contributor winner">👑</span>':'';return `<span class="avatar-award-wrap ${pc}${extra?` ${extra}`:''}" style="--avatar-accent:${accent}"><span class="${cls}"${fileId?` data-profile-photo-file="${esc(fileId)}" data-profile-photo-version="${esc(ver)}"`:''}>${esc(initials)}</span>${crown}</span>`}
  function compactUserIdentity(u={}){const badge=userFavoriteBadge(u),tag=cleanTagline(u.tagline||''),lvl=userLotLevel(u);return `${esc(u.profileDisplayName||u.userName||'User')}${badge?` ${esc(badge)}`:''} <span class="muted">LVL ${lvl}${tag?` - &quot;${esc(tag)}&quot;`:''}</span>`}
