  function carfaxBrandHtml(){return `<span class="carfax-mini-brand" aria-label="CARFAX"><i>C</i><i>A</i><i>R</i><i>F</i><i>A</i><i>X</i><b>✦</b></span>`}
  function carfaxFindingsHtml(o,compact=true){const parts=[];if(o?.carfaxOneOwner)parts.push(`<img class="carfax-badge-mini" src="./assets/carfax-one-owner.png" alt="One Owner">`);if(o?.carfaxLowKm)parts.push(`<img class="carfax-badge-mini" src="./assets/carfax-low-kilometres.png" alt="Low Odometer">`);if(o?.carfaxNoAccidents)parts.push(`<img class="carfax-badge-mini" src="./assets/carfax-no-reported-accidents.png" alt="No Accidents">`);return parts.length?`<span class="carfax-findings">${parts.join('')}</span>`:''}
  async function resolveDeletionRequests(v,status='approved',{sync=true}={}){const reports=getOpenDeletionRequests(v);if(!reports.length)return v;v.deletionRequests=getDeletionRequests(v).map(r=>{if(!r.resolvedAt && (r.status||'open')==='open')return {...r,status,resolvedAt:new Date().toISOString()};return r});v.updatedAt=Date.now();if(sync)v.syncStatus='pending';await DB.put('vehicles',v);for(const r of reports){if(status==='approved')await bumpModeration(r.reportedByUserName,'approved',1);else if(status==='false')await bumpModeration(r.reportedByUserName,'falseReports',1);await awardAdminRequestCompletion(r.id,'deletion')}if(sync)queueVehicleSync(v);return v}
  async function deleteVehicleEverywhere(v,{approveRequests=false}={}){const ls=await DB.byIndex('listings','vehicleId',v.id);if(approveRequests)await resolveDeletionRequests(v,'approved',{sync:false});if(v.drive?.profileFolderId){try{await DriveSync.deleteVehicle(v)}catch(err){if(!confirm('Could not remove the Drive folder: '+err.message+'\n\nDelete the local vehicle anyway?'))throw err}}for(const l of ls){try{await DriveSync.deleteListing(l)}catch{}await deleteListingCascade(l.id)}await DB.del('vehicles',v.id);return true}
  async function finishModerationReview(v,action,returnRoute='vehicles'){
    const reports=getOpenDeletionRequests(v);if(!reports.length){toast('No open removal requests remain.');modal.dataset.openToken='';modal.close();await go(returnRoute);return}
    if(action==='approve'){
      if(!confirm(`Approve ${reports.length} removal request${reports.length===1?'':'s'} and delete ${v.name||'this Vehicle Profile'}?`))return;
      await deleteVehicleEverywhere(v,{approveRequests:true});toast('Vehicle Profile deleted · all open requests approved');
    }else if(action==='deny'){
      if(!confirm(`Deny all ${reports.length} open removal request${reports.length===1?'':'s'}? Each reporting user will receive a False Report.`))return;
      await resolveDeletionRequests(v,'false');toast('Requests denied · False Report tallies updated');
    }else if(action==='remove'){
      if(!confirm(`Remove all ${reports.length} open removal request${reports.length===1?'':'s'} without affecting anyone's Request Ranking?`))return;
      await resolveDeletionRequests(v,'removed');toast('Removal requests cleared with no ranking change');
    }
    modal.dataset.openToken='';if(modal.open)modal.close();await go(returnRoute);
  }
