  function normalizeVehicleSearchText(value){return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
  function scoreVehicleSearch(v,q){
    const query=normalizeVehicleSearchText(q);if(!query)return 0;
    const tokens=query.split(/\s+/).filter(Boolean);
    const fields={year:normalizeVehicleSearchText(v.year),make:normalizeVehicleSearchText(v.make),model:normalizeVehicleSearchText(v.model),stock:normalizeVehicleSearchText(v.stock),vin:normalizeVehicleSearchText(v.vin),name:normalizeVehicleSearchText(v.name)};
    let total=0;
    for(const token of tokens){
      let best=0;
      for(const [key,val] of Object.entries(fields)){
        if(!val)continue;
        let score=0;
        if(val===token)score=12;
        else if(val.startsWith(token))score=9;
        else if(key==='year'&&val.endsWith(token))score=9;
        else if(val.includes(token))score=5;
        if((key==='stock'||key==='vin')&&val.includes(token))score+=3;
        if((key==='make'||key==='model')&&val.startsWith(token))score+=2;
        best=Math.max(best,score);
      }
      if(!best)return 0;
      total+=best;
    }
    const phrase=[fields.year,fields.make,fields.model,fields.stock].filter(Boolean).join(' ');
    if(phrase.includes(query))total+=8;
    return total;
  }
  function bestVehicleMatches(q,vehicles,limit=5){return (vehicles||[]).map(v=>({v,score:scoreVehicleSearch(v,q)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||String(a.v.name||'').localeCompare(String(b.v.name||''))).slice(0,limit)}
  async function renderSearch(q,vehicles,target){q=q.trim();if(!q){target.innerHTML='';return}const scored=bestVehicleMatches(q,vehicles,5);target.innerHTML=scored.length?`<div class="section-title"><h2>Best matches</h2><small>${scored.length} shown</small></div>${(await Promise.all(scored.map(x=>vehicleCard(x.v)))).join('')}`:empty('No matches');bindVehicleCards()}
