  async function copyText(text,label='Copied',button=null){
    text=String(text??'');
    const flash=()=>{if(!button)return;const old=button.textContent;button.classList.add('copy-flash');button.textContent='Copied ✓';setTimeout(()=>{button.classList.remove('copy-flash');button.textContent=old},900)};
    try{await navigator.clipboard.writeText(text);flash();toast(label+' ✓');return true}catch{}
    try{const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();document.execCommand('copy');ta.remove();flash();toast(label+' ✓');return true}catch{alert('Could not copy automatically. Press and hold the text to copy it.');return false}
  }
  function orderedListingPhotos(l,v){
    const all=listingAllPhotos(l,v);if(!all.length)return[];
    const byId=new Map(all.map(p=>[p.id,p]));
    return normalizePhotoOrder(l,v).map(id=>byId.get(id)).filter(Boolean);
  }
  async function hydrateListingAssets(l){
    const items=l?.listingAssets||[];let changed=false;
    await Promise.allSettled(items.map(async item=>{if(!item.blob&&item.driveFileId){item.blob=await DriveSync.fetchFileBlob(item.driveFileId);item.type=item.blob.type||item.type;item.size=item.blob.size||item.size;changed=true}}));
    if(changed)await DB.put('listings',l);
    return l;
  }
  function fileExt(item){
    const byName=(item?.name||'').match(/\.([a-z0-9]{2,5})$/i)?.[1];if(byName)return byName.toLowerCase();
    const type=(item?.type||item?.blob?.type||'').toLowerCase();
    return type.includes('png')?'png':type.includes('webp')?'webp':type.includes('heic')?'heic':'jpg';
  }
  function exportPhotoName(item,pos,l,v){
    const base=[l.year||v?.year,l.make||v?.make,l.model||v?.model,v?.stock].filter(Boolean).join(' ');
    const clean=String(base||'LotKeys Vehicle').replace(/[\\/:*?"<>|]/g,'-').trim()||'vehicle';return `${String(pos+1).padStart(2,'0')} - ${clean}.${fileExt(item)}`;
  }
  async function listingPhotoBlob(p){
    if(p?.blob)return p.blob;
    if(p?.driveFileId){
      try{return await DriveSync.fetchFileBlob(p.driveFileId)}catch(err){console.warn('Could not fetch photo from Drive',err)}
    }
    return null;
  }
  async function saveListingPhotosToFolder(l,v){
    const photos=orderedListingPhotos(l,v);
    if(!photos.length){alert('No listing photos are available yet.');return}
    if(!('showDirectoryPicker' in window)){
      return downloadListingPhotos(l,v);
    }
    try{
      const parent=await window.showDirectoryPicker({mode:'readwrite',startIn:'pictures'});
      const perm=parent.requestPermission?await parent.requestPermission({mode:'readwrite'}):'granted';
      if(perm!=='granted')throw new Error('Folder write permission was not granted.');
      const folderLabel=[v?.stock||l.marketplaceTitle||'Vehicle'].filter(Boolean).join(' - ');
      const outDir=await parent.getDirectoryHandle(`LotKeys - ${String(folderLabel).replace(/[\\/:*?"<>|]/g,'-')}`,{create:true});
      let saved=0;
      for(let i=0;i<photos.length;i++){
        const p=photos[i], blob=await listingPhotoBlob(p);
        if(!blob)continue;
        const handle=await outDir.getFileHandle(exportPhotoName(p,i,l,v),{create:true});
        const writable=await handle.createWritable();
        await writable.write(blob);
        await writable.close();
        saved++;
      }
      if(!saved)throw new Error('The photos were not available locally or from Google Drive.');
      toast(`${saved} photos saved to phone ✓`);
      alert(`Saved ${saved} ordered photos into the folder:\n\nLotKeys - ${folderLabel}\n\nIn Facebook, tap Add Photos and choose that folder.`);
    }catch(err){
      if(err?.name==='AbortError')return;
      alert('Could not save the photos to a folder:\n\n'+(err?.message||err)+'\n\nTry Download Photos instead.');
    }
  }
  async function downloadListingPhotos(l,v){
    const photos=orderedListingPhotos(l,v);
    if(!photos.length){alert('No listing photos are available yet.');return}
    if(!confirm(`Download ${photos.length} listing photos in the exact LotKeys order? Chrome may ask you to allow multiple downloads.`))return;
    let delay=0,started=0;
    for(let i=0;i<photos.length;i++){
      const p=photos[i], blob=await listingPhotoBlob(p);
      if(!blob)continue;
      setTimeout(()=>{const a=document.createElement('a');const u=URL.createObjectURL(blob);a.href=u;a.download=exportPhotoName(p,i,l,v);document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000)},delay);
      delay+=220;started++;
    }
    if(!started){alert('The photos were not available locally or from Google Drive.');return}
    toast('Photo downloads started');
  }
